//! Exact schema emitted by the historical version-seven journal implementation.
//!
//! Source: `ded1add8d^` (`488f106bad62ed3b9c94acd3744a5a1614a238ee`),
//! whose `JOURNAL_VERSION` is 7. A separate test program executed the unchanged
//! schema modules from this commit. The program replaced image import validation
//! types. The database contained no image import records. Turso sequence tables
//! are excluded; Turso creates them from `AUTOINCREMENT` declarations.
//! `journal_meta` is seeded dynamically so each test gets a fresh instance ID.

pub(in crate::journal) async fn install(
    connection: &turso::Connection,
) -> Result<(), crate::error::HostError> {
    for statement in STATEMENTS {
        connection
            .execute(statement, ())
            .await
            .map_err(|_| crate::error::HostError::Journal)?;
    }
    connection
        .execute(
            "INSERT INTO journal_meta (singleton, instance_id) VALUES (1, ?1)",
            [uuid::Uuid::new_v4().simple().to_string()],
        )
        .await
        .map_err(|_| crate::error::HostError::Journal)?;
    connection
        .execute("PRAGMA user_version = 7", ())
        .await
        .map_err(|_| crate::error::HostError::Journal)?;
    Ok(())
}

